To create an Ethereum Dapp that allows users to create and execute bets on a betting platform, you will need to write a smart contract in Solidity. Below is a basic implementation of such a smart contract. This contract allows users to create bets, join bets, and determine the winner based on a simple condition.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract BettingPlatform {
    struct Bet {
        uint id;
        address creator;
        address taker;
        uint amount;
        bool isTaken;
        bool isCompleted;
        address winner;
    }

    uint public betCounter;
    mapping(uint => Bet) public bets;

    event BetCreated(uint id, address creator, uint amount);
    event BetTaken(uint id, address taker);
    event BetCompleted(uint id, address winner);

    function createBet() external payable {
        require(msg.value > 0, "Bet amount must be greater than zero");

        betCounter++;
        bets[betCounter] = Bet({
            id: betCounter,
            creator: msg.sender,
            taker: address(0),
            amount: msg.value,
            isTaken: false,
            isCompleted: false,
            winner: address(0)
        });

        emit BetCreated(betCounter, msg.sender, msg.value);
    }

    function takeBet(uint betId) external payable {
        Bet storage bet = bets[betId];
        require(bet.id == betId, "Bet does not exist");
        require(!bet.isTaken, "Bet is already taken");
        require(msg.value == bet.amount, "Bet amount must match");

        bet.taker = msg.sender;
        bet.isTaken = true;

        emit BetTaken(betId, msg.sender);
    }

    function completeBet(uint betId, address winner) external {
        Bet storage bet = bets[betId];
        require(bet.id == betId, "Bet does not exist");
        require(bet.isTaken, "Bet is not taken yet");
        require(!bet.isCompleted, "Bet is already completed");
        require(msg.sender == bet.creator, "Only the creator can complete the bet");
        require(winner == bet.creator || winner == bet.taker, "Invalid winner address");

        bet.isCompleted = true;
        bet.winner = winner;

        payable(winner).transfer(bet.amount * 2);

        emit BetCompleted(betId, winner);
    }
}
```

### Explanation:

1. **Structs and State Variables**:
   - `Bet`: A struct to store information about each bet.
   - `betCounter`: A counter to keep track of the number of bets.
   - `bets`: A mapping to store bets by their ID.

2. **Events**:
   - `BetCreated`: Emitted when a new bet is created.
   - `BetTaken`: Emitted when a bet is taken by another user.
   - `BetCompleted`: Emitted when a bet is completed and a winner is determined.

3. **Functions**:
   - `createBet`: Allows a user to create a new bet by sending Ether. The bet amount is stored in the contract.
   - `takeBet`: Allows another user to take the bet by sending the same amount of Ether as the bet amount.
   - `completeBet`: Allows the creator of the bet to complete it and specify the winner. The winner receives the total amount of Ether from the bet.

### Deployment and Interaction:

To deploy and interact with this smart contract, you can use tools like Remix IDE, Truffle, or Hardhat. You will also need a web3 provider like MetaMask to interact with the contract from a frontend Dapp.

### Frontend Integration:

For a complete Dapp, you would typically create a frontend using a framework like React.js and use web3.js or ethers.js to interact with the deployed smart contract. This frontend would allow users to create, take, and complete bets through a user-friendly interface.

